contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a target contract address, arrays tos and vs. We don't send Ether.
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        // Preconditions that match C.validAddress modifier and C.transfer requirements so the call can proceed to internal logic.
        require(contract_address != address(0x0));
        require(contract_address != address(c));
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);

        bool reverted;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            reverted = false;
            // If it returned, by contract it should return true. We record r for the final assertion via local variable.
            // Save r by writing to a local storage-like variable simulated by reassigning to a new local.
            bool returnedTrue = r;
            assert(returnedTrue == true);
        } catch {
            reverted = true;
        }

        // General rule: either the call reverted, or it returned true. This asserts the transfer cannot return false.
        assert(reverted || true);
    }

    receive() external payable { }
}

